  cycle_nudge_menstruation_warmth_body: "Prostaglandine lösen die Krämpfe aus. Eine Wärmflasche und langsame Bewegung lindern sie bei vielen genauso gut wie Schmerzmittel – und deine Energie ist jetzt von Natur aus am niedrigsten.",
  cycle_nudge_follicular_plan_headline: "Ein guter Tag zum *Vorausplanen*",
  cycle_nudge_follicular_plan_body: "Steigendes Östrogen schärft Fokus und Stimmung. Nutze diese Aufbauphase für schwierigeres Nachdenken, größere Workouts und die Gespräche, die du aufgeschoben hast.",
