  cycle_nudge_ovulation_timing_body: "Spermien leben bis zu fünf Tage, die Eizelle nur 12 bis 24 Stunden. Konzentriere dich auf die Tage davor, nicht auf den genauen Tag – Häufigkeit schlägt Präzision.",
  cycle_nudge_luteal_sleep_headline: "Schütze diese Woche deinen *Schlaf*",
  cycle_nudge_luteal_sleep_body: "Progesteron hebt die Körpertemperatur und stört den Schlaf. Ein kühleres Zimmer und früheres Runterfahren stabilisieren die Stimmung mehr, als du erwartest.",
  cycle_nudge_luteal_move_headline: "Ein Spaziergang schlägt das *Grübeln*",
  cycle_nudge_luteal_move_body: "Tiefs in der späten Lutealphase sind hormonell, kein Urteil über dein Leben. Zwanzig Minuten Tageslicht und Bewegung setzen die Schleife besser zurück als Scrollen.",
  cycle_nudge_fertility_follicular_headline: "Dein Fenster *rückt näher*",
  cycle_nudge_fertility_follicular_body: "Östrogen baut sich Richtung Eisprung auf. Die fünf Tage vor dem Eisprung sind dein fruchtbares Fenster – Spermien können so lange auf die Eizelle warten.",
  cycle_nudge_fertility_luteal_headline: "Das Fenster hat sich *geschlossen*",
  cycle_nudge_fertility_luteal_body: "Die Eizelle lebt nur 12–24 Stunden, deshalb ist dieser Zyklusabschnitt wenig aussichtsreich. Wenn du getestet oder den Zeitpunkt abgepasst hast, heißt es jetzt einfach warten.",
  cycle_nudge_fertility_menstruation_headline: "Ein *frischer* Zyklus beginnt",
  cycle_nudge_fertility_menstruation_body: "Tag eins setzt die Uhr zurück. Dein nächstes fruchtbares Fenster liegt etwa zwei Wochen entfernt – eine ruhige Zeit zum Ausruhen und Vorbereiten, bevor es sich öffnet.",
  cycle_nudge_reflect_mood_headline: "Wie *fühlst* du dich heute?",
  cycle_nudge_reflect_mood_body: "Ein kurzer Stimmungscheck ergibt mit der Zeit ein Bild – Muster je nach Phase lassen sich leichter erkennen, wenn du ein paar Zyklen eingetragen hast.",
  cycle_nudge_reflect_symptom_headline: "Fällt dir heute *etwas* auf?",
  cycle_nudge_reflect_symptom_body: "Krämpfe, empfindliche Brüste, Kopfschmerzen? Wenn du Symptome einträgst, erkennst du mit deiner Ärztin oder deinem Arzt leichter, was bei dir üblich ist und was nicht.",
  cycle_nudge_reflect_energy_headline: "Wie steht es um deine *Energie*?",
  cycle_nudge_reflect_energy_body: "Die Energie sinkt vor der Periode ganz natürlich. Wenn du sie heute notierst, kannst du nach deinem eigenen Rhythmus planen, statt dagegen anzukämpfen.",
  cycle_nudge_nutrition_luteal_headline: "Greif zu *Magnesium*",
  cycle_nudge_nutrition_luteal_body: "Dunkle Schokolade, Mandeln, Kürbiskerne und Bananen lindern Krämpfe und stabilisieren die Stimmung in der zweiten Zyklushälfte. Kombiniere sie mit komplexen Kohlenhydraten, um Heißhunger zu mildern.",
  cycle_nudge_nutrition_ovulation_headline: "Nähre die *Eizelle*",
  cycle_nudge_nutrition_ovulation_body: "Antioxidantienreiche Lebensmittel – Beeren, Blattgemüse, Nüsse – unterstützen die Eizellqualität. Zink (Kürbiskerne, Kichererbsen) ist rund um den Eisprung besonders wichtig.",
  cycle_nudge_edu_menstruation_headline: "Deine Periode ist der *erste* Tag",
  cycle_nudge_edu_menstruation_body: "Zyklustag eins ist der erste Tag mit echter Blutung, nicht mit Schmierblutung. Von hier aus wird jede Vorhersage gezählt – wenn du ihn genau einträgst, wird alles treffsicherer.",
  cycle_nudge_edu_follicular_headline: "Ein Follikel *gewinnt*",
  cycle_nudge_edu_follicular_body: "In jedem Zyklus beginnen mehrere Follikel zu wachsen, aber meist reift nur einer und gibt eine Eizelle frei. Steigendes Östrogen steuert diese Auswahl.",
  cycle_nudge_edu_ovulation_headline: "Ein *36-Stunden*-Ereignis",
  cycle_nudge_edu_ovulation_body: "Der Eisprung selbst ist kurz – der LH-Anstieg löst die Freisetzung innerhalb von ca. 24–36 Stunden aus. Deshalb sind LH-Streifen darauf ausgelegt, den Anstieg zu erfassen, nicht die Freisetzung.",
  cycle_nudge_edu_luteal_headline: "Das *Zwei-Wochen*-Warten",
  cycle_nudge_edu_luteal_body: "Die Lutealphase ist bemerkenswert gleichmäßig – meist 12–14 Tage, unabhängig von der Zykluslänge. Die meisten Unterschiede zwischen Zyklen entstehen in der ersten Hälfte, nicht in dieser.",
  cycle_pillar_fertility: "Fruchtbarkeits-Basics",
