  cycle_conf_calendar: "Schätzung nach Kalender. Trag BBT + LH für die nächsten 3 Tage ein, um die Vorhersage zu schärfen.",
  cycle_conf_bbt_only: "Kalender + deine BBT. Ergänze LH-Streifen, um die Sicherheit über 90 % zu heben.",
  cycle_conf_bbt_lh: "Kalender + BBT + LH – die Sicherheit ist hoch. Wir warten noch auf den Temperaturanstieg nach dem Eisprung, um den Höhepunkt festzulegen.",
  cycle_conf_shift_confirmed: "BBT-Anstieg bestätigt. Der vergangene Höhepunkt steht fest. Künftige Fenster beruhen weiter auf dem Kalender.",
