  sw2_leap19_name: "Ereignisse",
  sw2_leap19_desc: "Verstehen, dass Handlungen nacheinander ablaufen",
  sw2_leap19_brain: "Um diese Zeit beginnen Babys oft, die Welt als Abfolge von Ereignissen statt als großes Durcheinander zu erleben. Handlungen haben einen Anfang, eine Mitte und ein Ende. Das ist der Beginn des Denkens in Ursache und Wirkung – und deshalb kann plötzlich alles so spannend wirken.",
  sw2_leap19_tip: "Spiele einfache Ursache-Wirkung-Spiele wie Guck-guck – dein Baby lernt, dass Ereignisse vorhersehbare Folgen haben.",
  sw2_leap19_ph0: "Anhänglich, weint beim Ablegen, unruhiger Schlaf. Dein Baby ist vielleicht erschöpft, weil so viel Neues auf einmal passiert.",
  sw2_leap19_ph1: "Dein Baby verbindet oft jede Handlung mit dem, was danach passiert – schieben, fallen lassen, genau hinschauen.",
  sw2_leap19_ph2: "Absichtliches Greifen taucht auf, dazu erste Anzeichen von Objektpermanenz – dein Baby sucht heruntergefallene Dinge.",
  sw2_leap19_sg0: "Mehr Trennungsangst",
  sw2_leap19_sg1: "Sehr anhänglich",
  sw2_leap19_sg2: "Weint, wenn ein Spielzeug fällt",
  sw2_leap19_sg3: "Wehrt sich gegen Nickerchen",
  sw2_leap19_sg4: "Verlangt Interaktion",
  sw2_leap19_sg5: "Frustriert, wenn die Routine sich ändert",
  sw2_leap19_sk0: "Greift gezielt nach Dingen",
  sw2_leap19_sk1: "Schüttelt und klopft Spielzeug",
  sw2_leap19_sk2: "Erkennt Spiele wieder",
  sw2_leap19_sk3: "Versteht „oben“ und „unten“",
  sw2_leap19_sk4: "Verfolgt bewegte Dinge mit den Augen",
  sw2_leap19_sk5: "Lacht über Überraschungen",
  sw2_leap19_ac0: "Guck-guck- und Versteckspiele",
  sw2_leap19_ac1: "Einen Ball hin- und herrollen",
  sw2_leap19_ac2: "Einfaches Ursache-Wirkung-Spielzeug (drücken = Ton)",
  sw2_leap19_ac3: "Erzähle den Alltag Schritt für Schritt",
  sw2_leap5_name: "Neue Sinneseindrücke",
  sw2_leap5_desc: "Das Baby entdeckt eine reichere Welt der Sinne",
  sw2_leap5_brain: "Etwa jetzt nimmt dein Baby über die Sinne vielleicht viel mehr Details wahr – schärfere Bilder, reichere Klänge, neue Körpergefühle. Das kann viel sein und zugleich wunderbar.",
  sw2_leap5_ph0: "Mehr Weinen, Anhänglichkeit und unruhiger Schlaf sind häufig. Das Baby nimmt vielleicht viele neue Sinneseindrücke auf.",
  sw2_leap5_ph1: "Das Baby nimmt viele neue Bilder und Geräusche auf. Die Quengeligkeit kann ihren Höhepunkt erreichen, bevor sie nachlässt.",
  sw2_leap5_ph2: "Die neue Sinneswahrnehmung blüht auf – du bemerkst längere Wachphasen und gezielteres Schauen.",
  sw2_leap5_sg0: "Weint mehr als sonst",
  sw2_leap5_sg1: "Will ständig trinken",
  sw2_leap5_sg2: "Schwerer zu beruhigen",
  sw2_leap5_sg3: "Mag es gern nah",
  sw2_leap5_sg4: "Erschrickt leichter",
  sw2_leap5_sg5: "Mag es nicht, ausgezogen zu werden",
  sw2_leap5_sk0: "Reagiert auf Licht und Geräusche",
  sw2_leap5_sk1: "Verfolgt Dinge flüssiger mit den Augen",
  sw2_leap5_sk2: "Erstes soziales Lächeln",
  sw2_leap5_sk3: "Mehr Wachphasen",
  sw2_leap5_sk4: "Wendet sich deiner Stimme zu",
  sw2_leap5_sk5: "Bemerkt kontrastreiche Muster",
  sw2_leap5_ac0: "Halte das Baby nach außen gewandt, damit es den Raum erkundet",
  sw2_leap5_ac1: "Zeige kontrastreiche Schwarz-Weiß-Karten",
  sw2_leap5_ac2: "Erzähle laut alles, was du tust",
  sw2_leap5_ac3: "Sanfte Babymassage in ruhigen Momenten",
  sw2_leap5_tip: "Hautkontakt ist jetzt besonders wertvoll. Tragen und sanftes Wiegen können unruhige Tage erleichtern.",
