  sw1_pa_weekShort: "W{{n}}",
  sw1_pa_wgT1: "Im ersten Trimester ändert sich das Gewicht oft nur wenig, und manche nehmen wegen der Übelkeit etwas ab.",
  sw1_pa_wgT2: "Im zweiten Trimester steigt das Gewicht oft gleichmäßig, während Baby und Plazenta wachsen.",
  sw1_pa_wgT3: "Im dritten Trimester verlangsamt sich die Zunahme oft. Sprich bei plötzlichen Schwellungen oder schnellen Veränderungen mit deinem Arzt oder deiner Hebamme.",
